pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(1000, "test", "TST"); }
    function testFuzz_property(uint256 burnAmount) public {
        burnAmount = bound(burnAmount, 1, 1000);

        address owner = c.owner();
        uint256 initialTotalSupply = c.totalSupply();
        uint256 initialOwnerBalance = c.balanceOf(owner);

        vm.prank(owner);
        c.burn(burnAmount);

        uint256 finalTotalSupply = c.totalSupply();
        uint256 finalOwnerBalance = c.balanceOf(owner);

        uint256 sumBalances = finalOwnerBalance;

        assertTrue(finalTotalSupply == sumBalances);
    }
}
